function comp(n){if(!MAP[n])throw new Error('missing '+n);return MAP[n].createInstance();}
function solid(hex){return {type:'SOLID',color:{r:parseInt(hex.slice(1,3),16)/255,g:parseInt(hex.slice(3,5),16)/255,b:parseInt(hex.slice(5,7),16)/255}};}
function paint(h){return (h&&h.type==='SOLID')?h:solid(h);}
const INK=paint('#1C1C28'),GRAY=paint('#8A8F98'),VIO=paint('#684DEC'),WHITE=paint('#FFFFFF');
