function recol(node,hex){const f=paint(hex);node.findAll(x=>'fills'in x&&x.fills&&x.fills.length&&x.fills[0].type==='SOLID').forEach(x=>x.fills=[f]);}
function F(name,x,y,h){const f=figma.createFrame();f.name=name;f.x=x;f.y=y;f.resize(375,h);f.fills=[WHITE];f.clipsContent=true;ws.appendChild(f);return f;}
