function bigBtn(f,label,x,y,w){const b=comp('Button');f.appendChild(b);b.resize(w,50);b.x=x;b.y=y;b.findAll(n=>n.type==='TEXT').forEach(t=>{t.characters=label;t.fontName={family:'Inter',style:'Semi Bold'};});b.findAll(n=>'fills'in n&&n.fills&&n.fills.length&&n.fills[0].type==='SOLID').forEach(n=>n.fills=[{type:'GRADIENT_LINEAR',gradientTransform:[[0,1,0],[-1,0,1]],gradientStops:[{position:0,color:{r:0.569,g:0.478,b:0.992,a:1}},{position:1,color:{r:0.384,g:0.275,b:0.918,a:1}}]}]);b.name=label;return b;}
